using System;
namespace HelmetHeroes
{
    public partial class GameCode
    {
        // Generated by tools/gen-map.mjs from data/map_<area>.json — do not edit by hand.
        private static byte[] MapB64(string s) { return s == null ? null : Convert.FromBase64String(s); }

        /// <summary>Hand-made map for the current area (replaces the procedural map).</summary>
        private bool TryApplyCustomMap()
        {
            switch (area)
            {
                case 1:
                    mapMain = MapB64("");
                    mapWater = MapB64("");
                    mapG2 = MapB64("");
                    mapG3 = MapB64("");
                    mapFG = MapB64("");
                    mapArt = MapB64("");
                    mapPortals.Clear();
                    mapPortals.Add(Pt(1, 22, 1));
                    spawnPoints.Clear();
                    spawnEnemyTypes.Clear();
                    playerSpawnOverride = null;
                    spawnPoints.Add(Pt4(8, 22, 5, 11));
                    spawnEnemyTypes.Add("");
                    spawnPoints.Add(Pt4(14, 22, 11, 17));
                    spawnEnemyTypes.Add("");
                    spawnPoints.Add(Pt4(14, 22, 11, 17));
                    spawnEnemyTypes.Add("");
                    spawnPoints.Add(Pt4(19, 22, 16, 22));
                    spawnEnemyTypes.Add("");
                    spawnPoints.Add(Pt4(24, 22, 21, 27));
                    spawnEnemyTypes.Add("");
                    return true;
            }
            return false;
        }
    }
}
